import React, { useEffect, useRef } from "react";

function Generate() {
  const canvasRef = useRef();

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const TILE_SIZE = 270;
    const GRID = 4;

    const imagePaths = JSON.parse(localStorage.getItem("selectedImages") || "[]");
    if (!imagePaths.length) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    Promise.all(
      imagePaths.map(
        (src) =>
          new Promise((resolve) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.src = src;
          })
      )
    ).then((images) => {
      // Draw one image for now
      ctx.drawImage(images[0], 0, 0, 1080, 1080);
    });
  }, []);

  return (
    <div>
      <h1>Generated Image</h1>
      <canvas ref={canvasRef} width={1080} height={1080} style={{ border: "1px solid #555" }} />
    </div>
  );
}

export default Generate;
